(12383, 1569, '_фотография', 'field_599079d3a25a6'),
(12384, 1569, 'должность', 'Акушер-Гинеколог, Врач УЗИ'),
(12385, 1569, '_должность', 'field_599079e2a25a7'),
(12386, 1569, 'краткое_описание', '<p style="text-align: center;"><strong>Специальность</strong></p>\r\n\r\n<ul>\r\n 	<li>Врач акушер-гинеколог; Репродуктолог.</li>\r\n</ul>\r\n<p style="text-align: center;"><strong>Опыт работы</strong></p>\r\n\r\n<ul>\r\n 	<li>Консультативный прием пациентов по специальности акушерство и гинекология;</li>\r\n 	<li>Знание методов современной контрацепции;</li>\r\n 	<li>Ведение беременности;</li>\r\n 	<li>Кольпоскопия;</li>\r\n 	<li>УЗИ-диагностика;</li>\r\n 	<li>Проведение малых гинекологических операций ("Сургитрон", биопсия, ВМС и тд.);</li>\r\n</ul>'),
(12387, 1569, '_краткое_описание', 'field_5990838f6563a'),
(12388, 1569, 'превью_фото', '1566'),
(12389, 1569, '_превью_фото', 'field_59915bfe5ab17'),
(12390, 1569, 'баннер_страницы', '1486'),
(12391, 1569, '_баннер_страницы', 'field_5990344362281'),
(12392, 1569, 'запись_на_баннере', 'Наши врачи'),
(12393, 1569, '_запись_на_баннере', 'field_59915bb64f5ee'),
