(12539, 1579, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:354;s:6:"height";i:401;s:4:"file";s:72:"2017/09/Анзимирова-Наталия-Вечеславовна.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:72:"Анзимирова-Наталия-Вечеславовна-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:72:"Анзимирова-Наталия-Вечеславовна-265x300.jpg";s:5:"width";i:265;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:12:{s:8:"aperture";s:2:"13";s:6:"credit";s:0:"";s:6:"camera";s:10:"NIKON D750";s:7:"caption";s:0:"";s:17:"created_timestamp";s:10:"1505401206";s:9:"copyright";s:0:"";s:12:"focal_length";s:2:"60";s:3:"iso";s:3:"200";s:13:"shutter_speed";s:4:"0.01";s:5:"title";s:0:"";s:11:"orientation";s:1:"1";s:8:"keywords";a:0:{}}}'),
