(25784, 3139, '_запись_на_баннере', 'field_59915bb64f5ee'),
(25787, 3140, 'имя', 'Ирина'),
(25788, 3140, '_имя', 'field_599079c4a25a4'),
(25789, 3140, 'фамилия', 'Вовк'),
(25790, 3140, '_фамилия', 'field_599079cca25a5'),
