(25831, 3142, 'имя', 'Нина'),
(25832, 3142, '_имя', 'field_599079c4a25a4'),
(25833, 3142, 'фамилия', 'Пастухова'),
(25834, 3142, '_фамилия', 'field_599079cca25a5'),
