 \r\n  	color: #fff;\r\n    font-size: 20px;\r\n    text-shadow: 1px 1px 1px #000;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n   box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.1) inset;\r\n	\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n	float: left;\r\n  	width: 80%;\r\n	margin-left: 10%;\r\n	text-align: center;\r\n	color: black;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n	color: #585858;\r\n    font-family: "Helvetica Neue",Helvetica,Arial,sans-serif;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: left;\r\n}\r\n\r\n\r\n\r\n', 'informed.jpg', 1, 1, 1, 1, 0, 0, 0, '2015-01-10 15:59:43', 5, 0);
