ground-size: cover;\r\n  	[endif]\r\n  \r\n  	color: #fff;\r\n    font-size: 20px;\r\n  	cursor: pointer;\r\n  	border-radius: 50%;\r\n 	width: 60px;\r\n  	height: 60px;\r\n  	padding-top: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n  	right: -20px !important;\r\n	top: -10px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n  	[if enb_subscribe]\r\n    color: #979696;\r\n    font-family: "Helvetica Neue",Helvetica,Arial,sans-serif;\r\n    font-size: xx-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n    text-align: left;\r\n  	margin-left: 10px;\r\n  	[else]\r\n  	margin-top: 10px;\r\n  	color: #979696;\r\n    font-family: "Helvetica Neue",Helvetica,Arial,sans-serif;\r\n    font-size: xx-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n    text-align: left;\r\n    margin-left: 10px;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n[if enb_subscribe]\r\n  [else]\r\n  	margin-top: 130px;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] li{\r\n	font-weight: bold;\r\n  	font-size: 13px;\r\n  	padding-top: 3px;\r\n	padding-bottom: 3px;\r\n  	color: #737E86;\r\n}', 'girl.png', 1, 1, 1, 1, 0, 0, 0, '2015-01-13 16:22:48', 6, 0),
(24, 'Grey', 1, 0, '', '<link rel="stylesheet" type="text/css" href="//fonts.googleapis.com/css?family=Didact+Gothic" />\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			<div style="clear: both;"></div>\r\n			<div class="ppsRightCol">\r\n				<div class="logo"></div>\r\n				[if enb_label]\r\n					<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n					[txt_0]\r\n					</div>\r\n				[endif]\r\n				<div style="clear: both;"></div>\r\n				[if enb_subscribe]\r\n					<div class="ppsSubscribeShell">\r\n						[sub_form_start]\r\n						[sub_fields_html]\r\n						<input class="singup" type="submit" name="submit" value="[sub_btn_label]" />\r\n						<input class="ppsPopupClose ppsPopupClose_[close_btn]" type="submit" name="submit" value="Close"/>\r\n						[sub_form_end]\r\n						<div style="clear: both;"></div>\r\n					</div>\r\n				[endif]\r\n				[if enb_sm]\r\n					<div class="ppsSm">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class="ppsFootNote">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: Georgia, Times, serif;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: table;\r\n  [if bg_type_0 == ''color'']\r\n	background:[bg_color_0]; \r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=''{{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}'', endColorstr=''[b