eight: 40px;\r\n	letter-spacing: -1px;\r\n	margin-top: 35px;\r\n	display: block;\r\n  	margin-bottom: 35px;;\r\n	padding-left: 20px;\r\n  	text-shadow: 1px 1px 2px black, 0 0 1em [bg_color_1];\r\n	-moz-text-shadow: 1px 1px 2px black, 0 0 1em [bg_color_1];\r\n	-webkit-text-shadow: 1px 1px 2px black, 0 0 1em [bg_color_1];\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 1% 1% 1% 1%;\r\n	text-align:right;\r\n	margin-bottom: 20px;\r\n  	padding-left: 20px;\r\n    margin: 0 auto;\r\n  	width: 60%;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	/*width: 100%;*/\r\n  	margin-bottom: 10px;\r\n  	height: 40px;\r\n  	border: 0px solid #d1b36d;\r\n	border-radius: 4px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	box-shadow: 2px 2px 2px #dcdcdc inset;\r\n  	padding-left: 20px;\r\n  	font-size: 15px;\r\n	width:100%;\r\n  	max-width: 284px;\r\n	display: block;\r\n	float: left;\r\n  	border: 1px solid #e2e2e2;\r\n  	margin-top: 1px;\r\n  	background-color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect {\r\n	display: table;\r\n  	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	display: table-cell;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel {\r\n	opacity: 0.5;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	width: 100%;\r\n  	background-color: transparent;\r\n  	height: 40px;\r\n  	border: none;\r\n  	font-size: 17px;\r\n  	border-radius: 4px !important;\r\n  	margin-left: -1px;\r\n}\r\n#