er: none;\r\n    background: #FFF;\r\n    font-size: 16px;\r\n    color: #7f7f7f;\r\n    margin-right: 0px!important;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	border-color: #000;\r\n	height: 43px;\r\n  	display:block;\r\n  	float: left;\r\n	margin-left: 10px;\r\n  	[if bg_type_4 == ''color'']\r\n  	background: [bg_color_4] 100%;\r\n   	box-shadow: -4px -4px 0px rgba(0, 0, 0, 0.1) inset;\r\n  	background-image: none;\r\n  	[elseif bg_type_1 == ''img'']\r\n  	background-image: url("[bg_img_1]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	color: #fff;\r\n    font-size: 16px;\r\n    text-shadow: 1px 1px 1px #000;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n   box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.1) inset;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell{\r\n    [if bg_type_3 == ''color'']\r\n  	background: [bg_color_3] 100%;\r\n  	[elseif bg_type_3 == ''img'']\r\n  	background-image: url("[bg_img_3]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n    float: left;\r\n    width: 100%;\r\n    padding: 40px 0 30px 0;\r\n}\r\n#ppsPopupShell_[ID] .logo-img{\r\n  	width:180px;\r\n  	height:180px;\r\n  	[if bg_type_2 == ''color'']\r\n	background: [bg_color_2]; \r\n  	[elseif bg_type_2 == ''img'']\r\n  	background-image: url("[bg_img_2]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	position: absolute; \r\n    right: 0;\r\n}\r\n#ppsPopupShell_[ID] .text-block {\r\n    position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n	float: left;\r\n  	width: 65%;\r\n	text-align: left;\r\n	color: #f37362;\r\n    font-size: 23px;\r\n    line-height: 30px;\r\n    padding-left: 10px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 li{\r\n	font-size: 18px;\r\n    color: #629296;\r\n    line-height: 26px;\r\n    display: inline-block;\r\n    padding-left: 25px;\r\n    margin-bo