(33, 'Simple HTML', 1, 0, '', '<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		[txt_0]\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: ''Helvetica'', arial;\r\n	font-size: 14px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] p {\r\n	margin: 14px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	height: 100%;\r\n  	[if bg_type_1 == ''color'']\r\n  	border: 8px solid [bg_color_1];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 10px;\r\n  	[if bg_type_0 == ''color'']\r\n  	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}', 'simple-html.jpg', 1, 1, 1, 5, 0, 0, 0, '2015-01-10 15:59:43', 31, 0),
(34, 'HTML 2 Columns', 1, 0, '', '<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n      	[if enb_txt_0]\r\n      	<div class="ppsCol">[txt_0]</div>\r\n      	[endif]\r\n      	[if enb_txt_1]\r\n      	<div class="ppsCol">[txt_1]</div>\r\n      	[endif]\r\n      	<div style="clear: both;"></div	>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: ''Helvetica'', arial;\r\n	font-size: 14px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #fff;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	height: 100%;\r\n  	[if bg_type_1 == ''color'']\r\n  	border: 8px solid [bg_color_1];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 10px;\r\n  	[if bg_type_0 == ''color'']\r\n  	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsCol {\r\n	float: left;\r\n  	margin: 0;\r\n  	padding: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsCol img {\r\n	width: 100% !important;\r\n  	height: auto !important;\r\n}\r\n{% if [enb_txt_0] and [enb_txt_1] %}\r\n#ppsPopupShell_[ID] .ppsCol {\r\n	width: 50%;\r\n}\r\n{% endif %}\r\n\r\n', 'html-2-columns.jpg', 1, 1, 1, 5, 0, 0, 0, '2015-01-10 15:59:43', 32, 0),
(35, 'PDF PopUp', 1, 0, '', '<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<iframe class="ppsMainFrame" src="https://docs.google.com/gview?url=[pdf_url]&embedded=true"></iframe>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	height: [height][height_measure];\r\n  	[if bg_type_0 == ''color'']\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsMainFrame {\r\n  	width: 100%;\r\n  	height: 100%;\r\n  	[if enb_bg_0]\r\n  	border: 8px solid [bg_color_0];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 0;\r\n  	margin: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n  	top: 15px;\r\n  	right: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}', 'pdf-popup.jpg', 1, 1, 1, 6, 0, 0, 0, '2015-01-10 15:59:43', 33, 0),
(38, 'Clear PopUp', 1, 0, '', '<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		[if enb_label]\r\n			<div class="ppsPopupLabel">[label]</div>\r\n		[endif]\r\n		[if enb_txt_0]\r\n			<div class="ppsPopupTxt ppsPopupTxt_0">[txt_0]</div>\r\n		[endif]\r\n		[if enb_btn_0]\r\n      		<a class="ppsBtn ppsBtn_0[if is_close_btn_0] ppsPopupClose[endif]" href="[btn_url_0]">[btn_txt_0]</a>\r\n      	[endif]\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: "Open Sans",arial;\r\n	font-size: 16px;\r\n	line-height: 1.475;\r\n	font-weight: normal;\r\n	color: #fff;\r\n  	text-shadow: 1px 1px 1px #000000;\r\n  	text-align: center;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	background-color: transparent;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 32px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsBtn {\r\n  	display: inline;\r\n  	margin: 0;\r\n  	padding: 5px 20px;\r\n  	border-radius: 5px;\r\n  	transition-duration: 0.3s;\r\n  	text-decoration: none !important;\r\n  	color: #fff;\r\n  	font-size: 24px;\r\n  	border: 1px solid #000;\r\n  	color: #000;\r\n  	[if bg_type_0 == ''color'']\r\n	background:  [bg_color_0]; /* Old browsers */\r\nbackground: -moz-linear-gradient(top,   {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* FF3.6-15 */\r\nbackground: -webkit-linear-gradient(top,   {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%,[bg_color_0] 100%); /* Chrome10-25,Safari5.1-6 */\r\nbackground: linear-gradient(to bottom,   {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%,[bg_color_0] 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr='' {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}'', endColorstr=''[bg_color_0]'',GradientType=0 ); /* IE6-9 */\r\n  	[elseif bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsBtn:hover,\r\n#ppsPopupShell_[ID] .ppsBtn:active {\r\n	[if bg_type_0 == ''color'']\r\n	/* Permalink - use to edit and share this gradient: http://colorzilla.com/gradient-editor/ [bg_color_0]+0,7db9e8+100 */\r\nbackground:  {{ adjust_brightness(popup.params.tpl.bg_color_0, -50) }}; /* Old browsers */\r\nbackground: -moz-linear-gradient(top,   [bg_color_0] 0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, -50) }} 100%); /* FF3.6-15 */\r\nbackground: -webkit-linear-gradient(top,   [bg_color_0] 0%,{{ adjust_brightness(popup.params.tpl.bg_color_0, -50) }} 100%); /* Chrome10-25,Safari5.1-6 */\r\nbackground: linear-gradient(to bottom,   [bg_color_0] 0%,{{ adjust_brightness(popup.params.tpl.bg_color_0, -50) }} 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr='' [bg_color_0]'', endColorstr=''{{ adjust_brightness(popup.params.tpl.bg_color_0, -50) }}'',GradientType=0 ); /* IE6-9 */\r\n  	[elseif bg_type_0 == ''img'']\r\n  	box-shadow: 1px 2px 1px #333;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	display: inline !important;\r\n}', 'clear-popup.jpg', 1, 1, 1, 8, 0, 0, 0, '2015-01-10 15:59:43', 21, 0),
(39, 'Video List Flat', 1, 0, '', '<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			[if enb_label]\r\n				<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n				<div style="clear: both;"></div>\r\n			[endif]\r\n			<div class="ppsPopupVideo ">\r\n				[video_html]\r\n			</div>\r\n			<div style="clear: both;"></div>\r\n		</div>\r\n		<div class="ppsRightCol">\r\n			[if enb_subscribe]\r\n				<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					<div style="clear: both;"></div>\r\n				</div>\r\n			[endif]\r\n			[if enb_sm]\r\n				<div class="ppsSm">\r\n				[sm_html]\r\n				</div>\r\n			[endif]\r\n			[if enb_foot_note]\r\n				<div class="ppsFootNote">\r\n				[foot_note]\r\n				</div>\r\n			[endif]\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: Georgia, Times, serif;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] iframe {\r\n	width: 100% !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: table;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  {% if popup.params.tpl.enb_subscribe or popup.params.tpl.enb_foot_note or popup.params.tpl.enb_sm %}\r\n  	width: 66%;\r\n	[else]\r\n  	width: 100%;\r\n  	[endif]\r\n  	display: table-cell;\r\n	[if bg_type_0 == ''color'']\r\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}), color-stop(100%, [bg_color_0])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ie10+ */\r\n	background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=''{{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}'', endColorstr=''[bg_color_0]'',GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	color: #000;\r\n	font-family: "Myriad Pro","Trebuchet MS","Helvetica Neue",Helvetica,Arial,Sans-Serif;\r\n	font-size: 30px;\r\n	letter-spacing: -1px;\r\n	line-height: 40px;\r\n	letter-spacing: -1px;\r\n	font-weight: bold;\r\n	margin-top: 15px;\r\n	margin-bottom: 16px;\r\n	padding-left: 20px;\r\n	text-shadow: 0px 0px 1px #000;\r\n	-moz-text-shadow: 0px 0px 1px #000;\r\n	-webkit-text-shadow: 0px 0px 1px #000;\r\n}\r\n#ppsPopupShell_[ID] .ppsRightCol {\r\n	display: table-cell;\r\n  	width: 34%;\r\n  	height: 100%;\r\n  	vertical-align: top;\r\n  	[if bg_type_1 == ''color'']\r\n  	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }}), color-stop(100%, [bg_color_1])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* ie10+ */\r\n  background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=''{{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }}'', endColorstr=''[bg_color_1]'',GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_1 == ''img'']\r\n  	background-image: url("[bg_img_1]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 30px 30px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	width: 100%;\r\n  	margin-bottom: 5px;\r\n  	height: 40px;\r\n  	border: none;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	box-shadow: 2px 2px 2px #dcdcdc inset;\r\n  	padding-left: 10px;\r\n  	font-size: 17px;\r\n  	background-color: #fff;\r\n  	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect {\r\n	display: table;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	display: table-cell;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel {\r\n	opacity: 0.5;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	width: 100%;\r\n  	background-color: transparent;\r\n  	height: 40px;\r\n  	border: none;\r\n  	margin-left: -5px;\r\n  	font-size: 17px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: inherit;\r\n  	height: auto;\r\n    padding-top: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text][name="email"] {\r\n	background-image: url("[PPS_ASSETS_URL]img/assets/mail-icon.png");\r\n  	background-repeat: no-repeat;\r\n  	background-position: 90% center;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n  	[if bg_type_2 == ''color'']\r\n  	background-color: [bg_color_2];\r\n  	background-image: none;\r\n  	[elseif bg_type_2 == ''img'']\r\n  	background-image: url("[bg_img_2]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	color: #fff;\r\n    font-size: 20px;\r\n    text-shadow: 2px 2px 2px #000;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n	box-shadow: inset 1px 1px 3px #666;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupVideo {\r\n  	width: 100%;\r\n  	line-height: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n	color: #585858;\r\n    font-family: "Helvetica Neue",Helvetica,Arial,sans-serif;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n}', 'video-list-flat.jpg', 1, 1, 1, 3, 0, 0, 0, '2015-01-10 15:59:43', 17, 0),
(40, 'List Building Neo', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Montserrat" rel="stylesheet"> \r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			[if enb_label]\r\n				<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			[if enb_txt_0]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n		</div>\r\n		<div class="ppsRightCol">\r\n			[if enb_subscribe]\r\n				<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					<div style="clear: both;"></div>\r\n				</div>\r\n			[endif]\r\n			[if enb_sm]\r\n				<div class="ppsSm">\r\n				[sm_html]\r\n				</div>\r\n			[endif]\r\n			[if enb_foot_note]\r\n				<div class="ppsFootNote">\r\n				[foot_note]\r\n				</div>\r\n			[endif]\r\n          	[if bg_type_3 == ''img'']\r\n				<img src="[bg_img_3]" class="ppsLogo" />\r\n			[endif]\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: "Montserrat","Trebuchet MS","Helvetica Neue",Helvetica,Arial,Sans-Serif;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #4d4d4d;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: table;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  {% if popup.params.tpl.enb_subscribe or popup.params.tpl.enb_foot_note or popup.params.tpl.enb_sm %}\r\n  	width: 66%;\r\n	[el