(41, 'Bright Girl', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Montserrat" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose"></a>\r\n	<div class="ppsPopupListsInner">\r\n		<div class="ppsPopupTblCols">\r\n          	[if bg_type_2 == ''img'']\r\n			<div class="ppsPopupLeftCol">\r\n				<img src="[bg_img_2]" class="ppsLogo" />\r\n			</div>\r\n          	[endif]\r\n			<div class="ppsPopupRightCol">\r\n				<div class="ppsBigArrow"></div>\r\n				[if enb_label]\r\n					<div class="ppsPopupLabel">[label]</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class="ppsPopupTxt ppsPopupTxt_0">[txt_0]</div>\r\n				[endif]\r\n				[if enb_subscribe]\r\n					<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					</div>\r\n				[endif]\r\n				[if enb_sm]\r\n					<div class="ppsSm">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class="ppsFootNote">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: "Montserrat",Helvetica,Arial,sans-serif;\r\n  	font-size: 14px;\r\n  	[if bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[elseif bg_type_0 == ''color'']\r\n  	background: [bg_color_0];\r\nbackground: -moz-linear-gradient(left, [bg_color_0] 0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 80) }} 31%, rgba(201,3,49,1) 56%, rgba(201,3,49,1) 67%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, [bg_color_0]), color-stop(31%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 80) }}), color-stop(56%, rgba(201,3,49,1)), color-stop(67%, rgba(201,3,49,1)));\r\nbackground: -webkit-linear-gradient(