n  	background: [bg_color_1];\r\n  	border: 1px solid transparent;\r\n  	color: #000;\r\n  	padding-left: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect {\r\n	display: table;\r\n  	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	display: table-cell;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel {\r\n	opacity: 0.5;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	width: 100%;\r\n  	background-color: transparent;\r\n  	height: 40px;\r\n  	border: none;\r\n  	font-size: 17px;\r\n  	color: #fff;\r\n  	margin-left: -15px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: inherit;\r\n  	height: auto;\r\n    padding: 20px 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	border: 1px solid #fff;\r\n  	[if bg_type_3 == ''color'']\r\n  	background: [bg_color_3];\r\n  	[elseif bg_type_3 == ''img'']\r\n  	background-image: url("[bg_img_3]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	color: #fff;\r\n    font-size: 20px;\r\n  	cursor: pointer;\r\n  	border-radius: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n  	right: -20px !important;\r\n	top: -10px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n  	[if enb_subscribe]\r\n    color: #979696;\r\n    font-size: xx-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n    text-align: left;\r\n  	margin-left: 10px;\r\n  	[else]\r\n  	margin-top: 10px;\r\n  	color: #979696;\r\n    font-size: xx-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n    text-align: left;\r\n    margin-left: 10px;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	[if e