(43, 'Smart New Edition', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Montserrat" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose"></a>\r\n	<div class="ppsPopupListsInner">\r\n		<div class="ppsPopupTblCols">\r\n			<div class="ppsPopupLeftCol">\r\n				[if bg_type_2 == "img"]\r\n				<img src="[bg_img_2]" />\r\n				[endif]\r\n			</div>\r\n			<div class="ppsPopupRightCol">\r\n				<div class="ppsBigArrow"></div>\r\n				[if enb_label]\r\n					<div class="ppsPopupLabel">[label]</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class="ppsPopupTxt ppsPopupTxt_0">[txt_0]</div>\r\n				[endif]\r\n				[if enb_subscribe]\r\n					<div class="ppsSubscribeShell">\r\n						[sub_form_start]\r\n						<div class="ppsFormWrap">\r\n						[sub_fields_html]\r\n						</div><!--\r\n						--><input type="submit" name="submit" value="[sub_btn_label]" />\r\n						[sub_form_end]\r\n					</div>\r\n				[endif]\r\n				[if enb_sm]\r\n					<div class="ppsSm">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class="ppsFootNote">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: Helvetica,Arial,sans-serif;\r\n  	font-size: 14px;\r\n  	[if bg_type_0 == "img"]\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupListsInner {\r\n  	[if bg_type_0 == "color"]\r\n	background: {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }}; /* Old browsers */\r\n	background: -moz-linear-gradient(top,  {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }} 0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 125) }} 50%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 60) }} 75%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }} 100%); /* FF3.6-15 */\r\n	background: -webkit-linear-gradient(top,  {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }} 0%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 125) }} 50%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 60) }} 75%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }} 100%); /* Chrome10-25,Safari5.1-6 */\r\n	background: linear-gradient(to bottom,  {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }} 0%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 125) }} 50%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 60) }} 75%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }} 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr="{{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }}", endColorstr="{{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }}",GradientType=0 ); /* IE6-9 */\r\n	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTblCols {\r\n	display: table;\r\n  	padding: 10px 10px 10px 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLeftCol {\r\n	display: table-cell;\r\n  	[if enb_subscribe]\r\n  	width: 30%;\r\n  	[else]\r\n  	width: 30%;\r\n  	min-height: 60%;\r\n  	[endif]\r\n  	vertical-align: middle;\r\n    text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupRightCol {\r\n  	width: 70%;\r\n	display: table-cell;\r\n  	border-radius: 8px;\r\n	-moz-border-radius: 8px;\r\n	-webkit-border-radius: 8px;\r\n  	margin: 8px 5px 5px 5px;\r\n  	text-align: left;\r\n  	padding: 30px 0 30px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input::-webkit-input-placeholder { /* Chrome/Opera/Safari */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input::-moz-placeholder { /* Firefox 19+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input:-ms-input-placeholder { /* IE 10+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input:-moz-placeholder { /* Firefox 18- */\r\n    color: #838383;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea::-webkit-input-placeholder { /* Chrome/Opera/Safari */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea::-moz-placeholder { /* Firefox 19+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea:-ms-input-placeholder { /* IE 10+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea:-moz-placeholder { /* Firefox 18- */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 30px 0 0;\r\n  	text-align: left;\r\n    position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsFormWrap {\r\n	display:inline-block;\r\n	width: 60%;\r\n	vertical-align: bottom;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="password"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	border: 1px solid transparent;\r\n	width: 100%;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	display:block;\r\n    font-size: 17px;\r\n	font-weight: normal;\r\n    color: #636363;\r\n	padding: 0 0 0 10px;\r\n	height: 40px;\r\n	margin: 10px 0 0 0;\r\n	\r\n  	[if bg_type_1 == "img"]\r\n  	background: url("[bg_img_1]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[else]\r\n  	background: [bg_color_1];\r\n  	[endif]\r\n  	\r\n  	[if bg_type_5 == "color"]\r\n  	color: [bg_color_5];\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	height: auto;\r\n	padding-top: 9px