(44, 'Christmas Mistletoe', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Great+Vibes|Lato" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			[if bg_type_1 == "img"]\r\n			<div class="ppsWrapImgCrn ppsWrapImgLftCrn">\r\n				<img class="ppsImgLftCrn" src="[bg_img_1]" alt="left image"/>\r\n			</div>\r\n			[endif]\r\n			[if bg_type_2 == "img"]\r\n			<div class="ppsWrapImgCrn ppsWrapImgRghtCrn">\r\n				<img class="ppsImgRghtCrn" src="[bg_img_2]" alt="rigth image"/>\r\n			</div>\r\n			[endif]\r\n			[if enb_label]\r\n				<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			[if enb_txt_0]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_txt_1]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1">\r\n				[txt_1]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					<div class="ppsFormWrap">\r\n					[sub_fields_html]\r\n					</div><input class="butt" type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					<div style="clear: both;"></div>\r\n				</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			<div class="ppsBottomtCol">\r\n				[if enb_sm]\r\n					<div style="clear: both;"></div>\r\n					<div class="ppsSm">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class="ppsFootNote">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: "Great Vibes";\r\n	font-weight: normal;\r\n	[if bg_type_0 == "color"]\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == "img"]\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n	text-align: center;\r\n	color: #fff;\r\n  	width: 100%;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n	width: 90%;\r\n	text-align: center;\r\n	display: inline-block;\r\n    margin: 40px 0 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	display: inline-block;\r\n    position: relative;\r\n    text-align: left;\r\n    width: 60%;\r\n    z-index: 100;\r\n}\r\n\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: "Lato";\r\n	font-size: 15px;\r\n	font-weight: normal;\r\n	border: 3px solid #fff;\r\n  	padding: 0 0 0 20px;\r\n	margin: 10px 0 0;\r\n	color: #fff;\r\n	width: 100%;\r\n	display: block;\r\n	vertical-align: top;\r\n	outline: none;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	\r\n  	[if bg_type_4 == "color"]\r\n  	background-color: [bg_color_4];\r\n    [elseif bg_type_4 == "img"]\r\n  	background-image: url("[bg_img_4]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n	[else]\r\n	background-color: transparent;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select  {\r\n	margin-top: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	font-family: "Lato";\r\n	font-size: 15px;\r\n	font-weight: normal;\r\n	display: block;\r\n	width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n	vertical-align: middle;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=radio],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=checkbox] {\r\n	vertical-align: middle;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	height: 42px;\r\n}\r\n#ppsPopupShell_[ID] .ppsFormWrap {\r\n	text-align: left;\r\n	width: 65%;\r\n	vertical-align: bottom;\r\n	display: inline-block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	font-family: "Lato";\r\n	font-size: 20px;\r\n	font-weight: normal;\r\n	width: 30%;\r\n  	text-align: center;\r\n 	cursor: pointer;\r\n  	text-decoration: none;\r\n  	color: #001933;\r\n  	display: inline-block;\r\n	vertical-align: bottom;\r\n	padding: 0px;\r\n	margin: 0;\r\n	border: none;\r\n	outline: none;\r\n	height: 42px;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	\r\n	[if bg_type_3 == "color"]\r\n  	background:[bg_color_3] !important;\r\n    [elseif bg_type_3 == "img"]\r\n  	background-image: url("[bg_img_3]") !important;\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsBottomtCol {\r\n	display: inline-block;\r\n	margin-bottom: 100px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	display: inline-block;\r\n	font-size: 30px;\r\n	width: 90%;\r\n	position: relative;\r\n	margin: 50px 30px 0;\r\n	z-index: 100;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	width: 90%;\r\n	text-align: center;\r\n	display: inline-block;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt  p {\r\n	padding: 0px;\r\n	margin: 0px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n  	font-size: 50px;\r\n	line-height: 51px;\r\n	margin-top: 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 p {\r\n	line-height: 51px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_1 {\r\n	margin-top: 30px;\r\n  	font-size: 25px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg {\r\n	display: block;\r\n	text-align: center;\r\n	width: 100%;\r\n	margin-top: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n  	right: -20px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n	color: #fff;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupShell .ppsErrorMsg{\r\n  width: 200px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsWrapImgCrn {\r\n	position: absolute;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgLftCrn {\r\n	top: 20px;\r\n	left: 12px;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgRghtCrn {\r\n	bottom: 20px;\r\n    right: 12px;\r\n}', 'christmas-mistletoe.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 15:59:43', 44, 0),
(45, 'XMas Sale', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Oxygen" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			<div class="ppsTopBgWrapper">\r\n				<div class="ppsWrapImgWr">\r\n					[if bg_type_1 == "img"]\r\n					<img src="[bg_img_1]" class="ppsImgWr"/>\r\n					[endif]\r\n				</div>\r\n				[if enb_label]\r\n					<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n					[txt_0]\r\n					</div>\r\n				[endif]\r\n				<div class="ppsSnow"></div>\r\n			</div>\r\n			<div style="clear: both;"></div>\r\n			[if enb_subscribe]\r\n				<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input class="butt" type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					<div style="clear: both;"></div>\r\n				</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			[if enb_sm]\r\n				<div style="clear: both;"></div>\r\n				<div class="ppsSm">\r\n				[sm_html]\r\n				</div>\r\n				\r\n			[endif]\r\n			[if enb_foot_note]\r\n				<div class="ppsFootNote">\r\n				[foot_note]\r\n				</div>\r\n			[endif]\r\n			<div class=""></div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: "Oxygen";\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n	[if bg_type_0 == "color"]\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == "img"]\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	position: relative;\r\n	text-align: center;\r\n	padding: 0 0 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n\r\n}\r\n\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n    \r\n    color: #4f4f4f;\r\n	text-align: center;\r\n	border: 2px solid #aaa;\r\n	font-family: "Oxygen";\r\n	font-size: 16px;\r\n	font-weight: normal;\r\n	width: 100%;\r\n	display:block;\r\n	margin-top: 10px;\r\n	height: 45px;\r\n	\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	[if bg_type_4 == "color"]\r\n	background: [bg_color_4];\r\n  	[elseif bg_type_4 == "img"]\r\n  	background-image: url("[bg_img_4]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	height: auto;\r\n	padding-top: 9px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select  {\r\n	display:inline-block;\r\n	margin-top: 0px\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	margin-top: 10px;\r\n	font-size: 16px;\r\n    color: #4f4f4f;\r\n	text-align: center;\r\n	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n	vertical-align: middle;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=radio],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=checkbox] {\r\n	vertical-align: middle;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email] {\r\n    \r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	display:block;\r\n	height: 45px;\r\n  	color: #fff;\r\n    font-size: 18px;\r\n	width: 100%;\r\n	margin: 10px 0;\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	border: 0 solid transparent;\r\n  	cursor: pointer;\r\n	text-transform: none;\r\n	padding: 0;\r\n	font-weight: 700;\r\n	font-family: "Oxygen";\r\n	[if bg_type_3 == "color"]\r\n	background: [bg_color_3];\r\n  	[elseif bg_type_3 == "img"]\r\n  	background-image: url("[bg_img_3]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n    display: inline-block;\r\n    margin: 40px 0 0;\r\n    width: 40%;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsTopBgWrapper {\r\n	[if bg_type_2 == "color"]\r\n	background: [bg_color_2];\r\n  	[elseif bg_type_2 == "img"]\r\n  	background-image: url("[bg_img_2]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	padding: 30px 0;\r\n	position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgWr {\r\n	display: inline-block;\r\n    text-align: center;\r\n    width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsImgWr {\r\n	display: inline-block;\r\n	max-width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 50px;\r\n	font-family: "Oxygen";\r\n	position: relative;\r\n	z-index: 100;\r\n	width: 90%;\r\n	display: inline-block;\r\n	padding-top: 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	margin: 0;\r\n	padding: 0;\r\n	text-align: center;\r\n	font-family: "Oxygen";\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt p {\r\n	display: inline-block;\r\n    margin: 0;\r\n    padding: 0;\r\n    width: 90%;\r\n	position: relative;\r\n	z-index: 100;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n    font-size: 20px;\r\n	padding-top: 30px;\r\n	font-weight: bold;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n    display: inline-block;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n	color: #4f4f4f;\r\n    margin: 5px 0px;\r\n    text-align: center;\r\n    width: 80%;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: center;\r\n}', 'x-mas-sale.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 15:59:43', 45, 0);
INSERT INTO `wp_pps_popup` (`id`, `label`, `active`, `original_id`, `params`, `html`, `css`, `img_preview`, `show_on`, `show_to`, `show_pages`, `type_id`, `views`, `unique_views`, `actions`, `date_created`, `sort_order`, `show_in_admin_area`) VALUES
(46, 'Merry Christmas', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Gentium+Basic" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			<div class="ppsWrapTopImg">\r\n				[if bg_type_1 == "img"]\r\n				<img src="[bg_img_1]" class="ppsTopImg"/>\r\n				[endif]\r\n			</div>\r\n			[if enb_label]\r\n				<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			[if enb_txt_0]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					<div style="clear: both;"></div>\r\n				</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			<div class="ppsBottomCol">\r\n				[if enb_sm]\r\n					<div style="clear: both;"></div>\r\n					<div class="ppsSm">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class="ppsFootNote">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: "Gentium Basic", arial;\r\n	font-size: 13px;\r\n	font-weight: normal;\r\n	color: #000;\r\n  	text-align: center;\r\n}\r\n\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n  	width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  	width: 100%;\r\n  	padding: 40px;\r\n	[if bg_type_0 == "color"]\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == "img"]\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapTopImg {\r\n	display: inline-block;\r\n    text-align: center;\r\n    width: 100%;\r\n	margin-bottom: 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsTopImg {\r\n	display: inline-block;\r\n	max-width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n	min-height: 200px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	width: 60%;\r\n	display: inline-block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: "Gentium Basic", arial;\r\n	font-size: 17px;\r\n	font-weight: normal;\r\n	border: 1px solid transparent;\r\n	width: 100%;\r\n	display: block;\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	height: 41px;\r\n	margin: 10px 0 0;\r\n	text-transform: none;\r\n	\r\n	padding-left: 15px;\r\n	background-image: none;\r\n	background-repeat: no-repeat;\r\n  	background-color: #fff;\r\n	color: #13316c;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	margin: 0;\r\n	min-height: 41px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	font-family: "Gentium Basic", arial;\r\n	font-size: 17px;\r\n	font-weight: normal;\r\n	display: block;\r\n	margin: 10px 0 0;\r\n	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n	vertical-align: middle;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=radio],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=checkbox] {\r\n	vertical-align: middle;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	height: auto;\r\n	padding-top: 9px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password], \r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email] {\r\n	padding-left: 35px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password] {\r\n	background-image: url("[PPS_ASSETS_URL]img/assets/user-black-icon.png");\r\n	background-position: 12px center;\r\n	\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email] {\r\n	background-image: url("[PPS_ASSETS_URL]img/assets/email-black-icon.png");\r\n	background-position: 10px center;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n  	[if bg_type_2 == "color"]\r\n	background: [bg_color_2];\r\n	background: -moz-linear-gradient(top, {{ adjust_brightness(popup.params.tpl.bg_color_2, 75) }} 26%, [bg_color_2] 100%);\r\n	background: -webkit-linear-gradient(top, {{ adjust_brightness(popup.params.tpl.bg_color_2, 75) }} 26%,[bg_color_2] 100%);\r\n	background: linear-gradient(to bottom, {{ adjust_brightness(popup.params.tpl.bg_color_2, 75) }} 26%,[bg_color_2] 100%);\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr="{{ adjust_brightness(popup.params.tpl.bg_color_2, 75) }}", endColorstr="[bg_color_2]",GradientType=0 );\r\n  	[elseif bg_type_2 == "img"]\r\n  	background-image: url("[bg_img_2]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	height: 41px;\r\n	text-transform: none;\r\n	margin: 10px 0 0;\r\n	-webkit-box-shadow: 2px 2px 6px 2px rgba(0, 0, 0, 0.75);\r\n	-moz-box-shadow: 2px 2px 6px 2px rgba(0, 0, 0, 0.75);\r\n	box-shadow: 2px 2px 6px 2px rgba(0, 0, 0, 0.75);\r\n	padding: 0;\r\n  	cursor: pointer;\r\n	color: #fff;\r\n	font-size: 20px;\r\n	font-family: "Gentium Basic", arial;\r\n	font-weight: normal;\r\n	border: 1px solid transparent;\r\n	width: 100%;\r\n	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n	-webkit-box-shadow: 2px 2px  7px 2px rgba(0, 0, 0, 0.75);\r\n	-moz-box-shadow: 2px 2px  7px 2px rgba(0, 0, 0, 0.75);\r\n	box-shadow: 2px 2px  7px 2px rgba(0, 0, 0, 0.75);\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 40px;\r\n	line-height: 40px;\r\n	font-weight: bold;\r\n  	margin: 0 30px 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n  	width: 100%;\r\n	font-size: 14px;\r\n  	margin: 0 30px 20px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n  	right: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n	color: #585858;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm {\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg {\r\n	margin: 0px;\r\n}', 'merry-christmas.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 15:59:43', 46, 0),
(47, 'Christmas Recipes', 1, 0, '', '<link href="https://fonts.google.com/?query=Open+sans&selection.family=Open+Sans:400,700" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			<div class="ppsTopBgWrapper">\r\n				<div class="ppsWrapImgWr">\r\n					[if enb_label]\r\n						<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n					[endif]\r\n					[if enb_txt_0]\r\n						<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n						[txt_0]\r\n						</div>\r\n					[endif]\r\n					[if enb_txt_1]\r\n						<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1">\r\n						[txt_1]\r\n						</div>\r\n					[endif]\r\n				</div>\r\n			</div>\r\n			<div style="clear: both;"></div>\r\n			<div class="ppsBtmBgWrapper">\r\n				[if enb_txt_2]\r\n					<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_2 ppsPopupTxt_2">\r\n					[txt_2]\r\n					</div>\r\n				[endif]\r\n				[if enb_subscribe]\r\n					<div class="ppsSubscribeShell">\r\n						[sub_form_start]\r\n						[sub_fields_html]\r\n						<input class="butt" type="submit" name="submit" value="[sub_btn_label]" />\r\n						[if enb_foot_note]\r\n							<a href="#" class="ppsFootNote ppsPopupClose">\r\n							[foot_note]\r\n							</a>\r\n						[endif]\r\n						[sub_form_end]\r\n						<div style="clear: both;"></div>\r\n					</div>\r\n				[endif]\r\n				<div style="clear: both;"></div>\r\n				[if enb_sm]\r\n					<div style="clear: both;"></div>\r\n					<div class="ppsSm">\r\n					[sm_html]\r\n					</div>\r\n					\r\n				[endif]\r\n			</div>\r\n			<div class="ppsBtmLine"></div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: "Open Sans", arial;\r\n	font-size: 13px;\r\n	line-height: normal;\r\n	font-weight: normal;\r\n	color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n	[if bg_type_0 == "color"]\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == "img"]\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	position: relative;\r\n	text-align: center;\r\n	padding: 0;\r\n}\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	margin: 10px 0 0;\r\n	font-size: 16px;\r\n	font-family: "Open Sans", arial;\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	border: 2px solid #ccc;\r\n	width: 100%;\r\n	display:block;\r\n	background: #fff;\r\n	color: #4f4f4f;\r\n	text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select  {\r\n	font-size: 16px;\r\n	font-family: "Open Sans", arial;\r\n	border: 2px solid #ccc;\r\n	display: inline-block;\r\n	background: #fff;\r\n	color: #4f4f4f;\r\n	text-align: center;\r\n	height: 45px;\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	color: #333333;\r\n    display: block;\r\n    margin: 10px 0 0;\r\n	font-size: 16px;\r\n	font-family: "Open Sans", arial;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email] {\r\n    height: 45px;\r\n}\r\n#ppsPopupShell_[ID] input[type=submit] {\r\n	font-family: "Open Sans", arial;\r\n	display:inline-block;\r\n  	color: #fff;\r\n    font-size: 18px;\r\n	width: auto;\r\n	margin: 10px 0;\r\n	-webkit-border-radius: 35px;\r\n	-moz-border-radius: 35px;\r\n	border-radius: 35px;\r\n	border: 0 solid transparent;\r\n  	cursor: pointer;\r\n	text-transform: none;\r\n	padding: 13px 88px 7px 60px;\r\n	font-weight: 700;\r\n	text-shadow: 1px 2px 0px #86B80E;\r\n	text-decoration: none;text-decoration: none;\r\n	\r\n	-webkit-box-shadow: 1px 4px 0 0 rgba(134, 184, 14, 1);\r\n	-moz-box-shadow: 1px 4px 0 0 rgba(134, 184, 14, 1);\r\n	box-shadow: 1px 4px 0 0 rgba(134, 184, 14, 1);\r\n\r\n	background-color: #9cd610;\r\n	background-image: url("[PPS_ASSETS_URL]img/assets/365-1-arr-dwn.png");\r\n    background-position: 79% 13px;\r\n    background-repeat: no-repeat;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input.butt + a.ppsPopupClose {\r\n	display: inline-block !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n    display: inline-block;\r\n    margin: 20px 0 20px;\r\n    width: 60%;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsTopBgWrapper {\r\n	[if bg_type_1 == "color"]\r\n	background: [bg_color_1];\r\n  	[elseif bg_type_1 == "img"]\r\n  	background-image: url("[bg_img_1]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	padding: 70px 0 0;\r\n	position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgWr {\r\n	[if bg_type_2 == "color"]\r\n	background: {{ hex_to_rgba_str(popup.params.tpl.bg_color_2, 0.5) }};\r\n  	[elseif bg_type_2 == "img"]\r\n  	background-image: url("[bg_img_2]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	display: inline-block;\r\n    min-height: 130px;\r\n    padding: 10px 0;\r\n    text-align: center;\r\n    width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsImgWr {\r\n	display: inline-block;\r\n	max-width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 50px;\r\n	position: relative;\r\n	z-index: 100;\r\n	width: 90%;\r\n	display: inline-block;\r\n	padding-top: 30px;\r\n	font-family: "Open Sans", arial;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	margin: 0;\r\n	padding: 0;\r\n	text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt p {\r\n	display: inline-block;\r\n    margin: 0;\r\n    padding: 0;\r\n    width: 90%;\r\n	position: relative;\r\n	z-index: 100;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n    font-size: 63px;\r\n    font-weight: bold;\r\n	font-family: "Open Sans", arial;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_1 {\r\n    color: #ffb2b2;\r\n    font-size: 56px;\r\n    font-weight: bold;\r\n    line-height: 51px;\r\n	font-family: "Open Sans", arial;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_2 {\r\n    color: #333333;\r\n    font-size: 21px;\r\n    font-weight: bold;\r\n	font-family: "Open Sans", arial;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsBtmBgWrapper {\r\n	padding: 20px 0 0;\r\n	position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsBtnOne:hover {\r\n	text-decoration: none;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsBtmLine {\r\n	height: 5px;\r\n	\r\n	[if bg_type_3 == "color"]\r\n	background: {{ hex_to_rgba_str(popup.params.tpl.bg_color_3, 0.5) }} !important;\r\n  	[elseif bg_type_3 == "img"]\r\n  	background-image: url("[bg_img_3]") !important;\r\n  	background-repeat: no-repeat !important; \r\n  	background-size: cover !important;\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	z-index: 1000;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n	border-bottom: 2px dotted #b7b7b7;\r\n    color: #b7b7b7;\r\n	display: none !important;\r\n	margin: 10px 0;\r\n	text-decoration: none;	\r\n	background: none !important;\r\n	font-size: 16px;\r\n    height: auto !important;\r\n    position: static !important;\r\n    width: auto !important;\r\n	top: 0 !important;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote:hover {\r\n	text-decoration: none;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: center;\r\n}', 'christmas-1-prev.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 15:59:43', 47, 0);
INSERT INTO `wp_pps_popup` (`id`, `label`, `active`, `original_id`, `params`, `html`, `css`, `img_preview`, `show_on`, `show_to`, `show_pages`, `type_id`, `views`, `unique_views`, `actions`, `date_created`, `sort_order`, `show_in_admin_area`) VALUES
(48, 'Christmas mood', 1, 0, '', '<link href="https://fonts.googleapis.com/css?family=Alex+Brush|Josefin+Sans" rel="stylesheet">\r\n<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n	<a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n	<div class="ppsInnerTblContent">\r\n		<div class="ppsPopupListsInner ppsPopupInner">\r\n			<div class="ppsWrapTopImg">\r\n				[if bg_type_1 == "img"]\r\n				<img src="[bg_img_1]" class="ppsTopImg"/>\r\n				[endif]\r\n			</div>\r\n			[if enb_label]\r\n				<div class="ppsPopupLabel ppsPopupListsLabel">[label]</div>\r\n			[endif]\r\n			[if enb_txt_0]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0">\r\n				[txt_0]\r\n				</div>\r\n				<div class="ppsTxt1Separator"></div>\r\n			[endif]\r\n			[if enb_txt_1]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1">\r\n				[txt_1]\r\n				</div>\r\n			[endif]\r\n			<div style="clear: both;"></div>\r\n			[if enb_subscribe]\r\n				<div class="ppsSubscribeShell">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input class="butt" type="submit" name="submit" value="[sub_btn_label]" />\r\n					[sub_form_end]\r\n					<div style="clear: both;"></div>\r\n				</div>\r\n			[endif]\r\n			[if enb_txt_2]\r\n				<div class="ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_2 ppsPopupTxt_2">\r\n				[txt_2]\r\n				</div>\r\n			[endif]\r\n			<div class="ppsTxt1Separator"></div>\r\n			[if enb_foot_note]\r\n				<a href="#" class="ppsFootNote ppsPopupClose">\r\n				[foot_note]\r\n				</a>\r\n			[endif]\r\n			\r\n			<div style="clear: both;"></div>\r\n			[if enb_sm]\r\n				<div style="clear: both;"></div>\r\n				<div class="ppsSm">\r\n				[sm_html]\r\n				</div>\r\n			[endif]\r\n			\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: arial;\r\n	font-size: 13px;\r\n	font-weight: normal;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n}\r\n\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n	[if bg_type_0 == "color"]\r\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}), color-stop(100%, [bg_color_0])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ie10+ */\r\n	background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr="{{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}", endColorstr="[bg_color_0]",GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_0 == "img"]\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	position: relative;\r\n	text-align: center;\r\n	padding: 0 0 40px;\r\n	[if bg_type_3 == "color"]\r\n	border: 3px solid [bg_color_3];\r\n	[endif]\r\n	\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell{\r\n    display: inline-block;\r\n    margin: 0;\r\n    width: 60%;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="email"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type="text"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	width: 100%;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	border: 1px solid transparent;\r\n	height: 47px;\r\n	padding: 0;\r\n	margin: 10px 0;\r\n	display:block;\r\n	text-align: center;\r\n	color: #016823;\r\n	font-weight: normal;\r\n	font-size: 18px;\r\n	font-family: arial;\r\n	\r\n	[if bg_type_2 == "color"]\r\n	background: [bg_color_2];\r\n  	[elseif bg_type_2 == "img"]\r\n  	background-image: url("[bg_img_2]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	margin: 0px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea { \r\n	height: auto;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	display:block;\r\n	margin: 10px 0 0;\r\n	color: #016823;\r\n	font-weight: normal;\r\n	font-size: 18px;\r\n	font-family: arial;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n	vertical-align: middle;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=radio],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=checkbox] {\r\n	vertical-align: middle;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email] {\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input::-webkit-input-placeholder { /* Chrome/Opera/Safari */\r\n    color: #016823;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input::-moz-placeholder { /* Firefox 19+ */\r\n    color: #016823;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell inpu:-ms-input-placeholder { /* IE 10+ */\r\n    color: #016823;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input:-moz-placeholder { /* Firefox 18- */\r\n    color: #016823;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	\r\n	width: 100%;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	border: 1px solid transparent;\r\n	height: 47px;\r\n	padding: 0;\r\n	margin: 10px 0;\r\n	text-align: center;\r\n	font-family: arial;\r\n	\r\n  	color: #fff;\r\n  	cursor: pointer;\r\n	text-transform: none;\r\n	font-weight: 700;\r\n	font-size: 20px;\r\n	display: inline-block;\r\n	border: 1px solid transparent;\r\n	\r\n	background-color: #016823;\r\n    background-image: url("[PPS_ASSETS_URL]img/assets/365-2-right-arr.png");\r\n    background-position: 90% center;\r\n    background-repeat: no-repeat;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapTopImg {\r\n	display: inline-block;\r\n    text-align: center;\r\n    width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsTopImg {\r\n	display: inline-block;\r\n	max-width: 70%;\r\n}\r\n\r\n\r\n\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-family: arial;\r\n	font-size: 35px;\r\n	padding: 20px 20px 0; \r\n	text-align: center;\r\n	line-height: 45px;\r\n	position: relative;\r\n	z-index: 100;\r\n	color: #333333;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	font-family: arial;\r\n	margin: 0;\r\n	padding: 0;\r\n	text-align: center;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt p {\r\n	display: inline-block;\r\n    margin: 0;\r\n    padding: 0;\r\n    width: 90%;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n    color: #f2362d;\r\n    font-size: 70px;\r\n    font-weight: bold;\r\n    line-height: 60px;\r\n    margin: 10px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_1 {\r\n    color: #333333;\r\n    font-size: 18px;\r\n    padding: 10px 0;\r\n}\r\n\r\n\r\n#ppsPopupShell_[ID] .ppsPopupTxt_2 {\r\n	display: block;\r\n    font-size: 16px;\r\n    margin: 0 auto 15px;\r\n    text-align: center;\r\n    width: 90%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_2 a {\r\n	color: #f44b44;\r\n	text-decoration: none;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_2 a:hover {\r\n	text-decoration: none;\r\n}\r\n\r\n\r\n#ppsPopupShell_[ID] .ppsTxt1Separator {\r\n	background-color: #cccccc;\r\n    display: block;\r\n    height: 1px;\r\n    margin: 0 auto;\r\n    width: 15%;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n	z-index: 1000 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n    background: none !important;\r\n    border-bottom: 2px solid #016823;\r\n    color: #016823;\r\n    display: inline-block !important;\r\n    font-size: 16px;\r\n    height: auto !important;\r\n    margin: 10px 0;\r\n    position: static !important;\r\n    text-decoration: none;\r\n    top: 0 !important;\r\n    width: auto !important;\r\n	\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: center;\r\n}\r\n', 'christmas-2-prev.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 15:59:43', 48, 0),
