l]::-moz-placeholder { /* Firefox 19+ */\r\n    color: #999999;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email]:-ms-input-placeholder { /* IE 10+ */\r\n    color: #999999;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email]:-moz-placeholder { /* Firefox 18- */\r\n    color: #999999;\r\n}\r\n\r\n\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-family: arial;\r\n	font-size: 35px;\r\n	padding: 20px 20px 0; \r\n	text-align: center;\r\n	line-height: 45px;\r\n	position: relative;\r\n	z-index: 100;\r\n	color: #fff;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	font-family: arial;\r\n	margin: 0;\r\n	padding: 0;\r\n	text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt p {\r\n	display: inline-block;\r\n    margin: 0;\r\n    padding: 0;\r\n    width: 90%;\r\n	position: relative;\r\n	z-index: 100;\r\n	word-wrap: break-word;\r\n	line-height: 50px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n    color: #fff;\r\n    font-size: 53px;\r\n    line-height: 50px;\r\n    margin: 10px 0;\r\n	text-shadow: 2px 2px 0 #01a2ea;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] + .ppsFootNote {\r\n	display: inline-block !important;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n	-webkit-border-radius: 10px;\r\n	-moz-border-radius: 10px;\r\n	border-radius: 10px;\r\n	\r\n	background: none !important;\r\n	border: 2px solid #cbcbcb;\r\n    color: #cbcbcb;\r\n    display: none !important;\r\n    font-size: 16px;\r\n	font-weight: bold;\r\n    height: auto !important;\r\n    margin: 60px 30px 0;\r\n	padding: 5px 20px;\r\n    position: static !important;\r\n    text-decoration: none;\r\n    top: 0 !important;\r\n    width: auto !important;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n	z-index: 1000 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: center;\r\n}\r\n', 'christmas-3-prev.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 15:59:43', 49, 0),
(100, 'Дорогие и любимые пациенты  Клиники Современных Технологий!', 0, 33, '', '<div id="ppsPopupShell_[ID]" class="ppsPopupShell ppsPopupListsShell">\r\n\r\n  <a href="#" class="ppsPopupClose ppsPopupClose_[close_btn]"></a>\r\n\r\n	<div class="ppsInnerTblContent">\r\n	\r\n		[txt_0]\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: ''Helvetica'', arial;\r\n	font-size: 14px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] p {\r\n	margin: 14px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	height: 100%;\r\n  	[if bg_type_1 == ''color'']\r\n  	border: 8px solid [bg_color_1];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 10px;\r\n  	[if bg_type_0 == ''color'']\r\n  	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == ''img'']\r\n  	background-image: url("[bg_img_0]");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n<script type="text/javascript">\r\nwindow.onload=function(){snow(1);}\r\n\r\nfunction snow(id){\r\n var png_sh=Math.floor(Math.random()*5)+1;\r\n var pos_x=Math.floor(Math.random()*98)+1;\r\n var step=Math.floor(Math.random()*30)-15;\r\n\r\n var end_x=pos_x+step;\r\n var img="<img id=''snow_" + id + "'' style=''left:" + pos_x +\r\n "%; top:-10%; position:fixed;'' src=''/wp-content/uploads/2017/12/flake"+png_sh+".gif''>";\r\n $("#snow").append(img);\r\n move_show(id,end_x);\r\n id++;\r\n setTimeout("snow("+id+");",150);\r\n}\r\nfunction move_show(id,end_x){\r\n $("#snow_"+id).animate({top:"120%",left:""+end_x+"%"},20000,function(){\r\n  $("#snow_"+id).empty().remove();\r\n });\r\n}\r\n</script>\r\n<script type="text/javascript"\r\nsrc="https://ajax.googleapis.com/ajax/libs/jquery/1.12.4/jquery.min.js"></script>', 'simple-html.jpg', 1, 2, 2, 5, 1105, 692, 0, '2015-01-10 15:59:43', 0, 0);
